INSERT INTO question_option_translations(option_id,locale,label,description) SELECT o.id,'mt','Titjib ta’ sit web eżistenti',NULL FROM question_options o JOIN service_questions q ON q.id=o.question_id JOIN marketplace_services s ON s.id=q.service_id WHERE s.code='WEBSITE_DEVELOPMENT' AND q.question_key='website_work' AND o.option_value='IMPROVE';
